/** Resolve a local /public icon path for an address or symbol, or null. */
export function getLocalTokenIcon(key: string): string | null {
  const file = LOCAL_TOKEN_ICONS[key.toLowerCase()];
  return file ? `/icons/tokens/${file}` : null;
}
